SELECT bsch.change_id AS changeId, bsch.branch_stock_code AS branchStockCode, bsch.change_amount AS changeAmount, bsch.change_type AS changeType, bsch.after_qty AS afterQty, DATE_FORMAT(bsch.changed_at, '%Y-%m-%d %H:%i') AS changedAt, m.material_name AS materialName, mg.group_name AS groupName, bs.expire_date AS expireDate FROM branch_stock_change_history bsch JOIN branch_stock bs ON bsch.branch_stock_code = bs.branch_stock_code JOIN material m ON bs.material_code = m.material_code JOIN material_group mg ON m.material_group_id = mg.material_group_id WHERE bs.branch_code = #{branchCode}
AND mg.material_group_id = #{materialGroupId}
AND m.material_name = #{materialName}
AND DATE(bsch.changed_at) >= #{startDate}
AND DATE(bsch.changed_at) <= #{endDate}
ORDER BY bsch.changed_at DESC LIMIT #{pageSize} OFFSET #{offset}

